export default function read({ body }) {
  const labels = Array.isArray(body?.labels?.nodes)
    ? body.labels.nodes
    : Array.isArray(body?.labels)
      ? body.labels
      : [];
  return {
    eligible:
      typeof body?.priority === "number" &&
      body.priority >= 3 &&
      labels.some((l) => l?.name === "bug"),
    title: String(body?.title || ""),
    url: String(body?.url || ""),
  };
}

