export default async function pick({ events }, ctx) {
  let s = await ctx.state.get("cursor:" + ctx.nodeId);
  if (!s || s.runId !== ctx.runId) s = { runId: ctx.runId, index: 0 };
  if (!Array.isArray(events) || s.index >= events.length) return { hasMore: false, issueId: "" };
  const ev = events[s.index];
  await ctx.state.set("cursor:" + ctx.nodeId, { runId: ctx.runId, index: s.index + 1 });
  return { hasMore: true, issueId: String(ev.id || "") };
}
